USE pos_refactor;


-- Items per transaksi (1 item per transaksi untuk simplisitas)
SELECT 
  t.id,
  p.id,
  p.name,
  p.barcode,
  1,
  p.price,
  p.price,
  t.created_at
FROM transactions t
JOIN products p ON p.id = (1 + (t.id % 10))
WHERE t.cashier_name = 'Demo Kasir'
  AND NOT EXISTS (
    SELECT 1 FROM transaction_items ti WHERE ti.transaction_id = t.id
  );